package au.monster.tracker;

import java.util.*;

public final class PurchaseTests {
    private static long now=CoreTests.NOW;
    private static Purchases.Line line(){return new Purchases.Line("purchase-line01","Monster Original",2,24,10001,909,true);}
    private static Map<String,Object> bundle(Purchases.Document d,Purchases.Receipt receipt){Map<String,Object> all=new LinkedHashMap<>();all.put("documents",Ledger.list(Purchases.documentMap(d)));List<Object> receipts=new ArrayList<>();if(receipt!=null){Map<String,Object> r=new LinkedHashMap<>();r.put("hash",receipt.hash());r.put("mime",receipt.mime());r.put("content",Base64.getEncoder().encodeToString(receipt.content()));receipts.add(r);}all.put("receipts",receipts);all.put("deliveries",new ArrayList<>());all.put("cancellations",new ArrayList<>());all.put("audit",new ArrayList<>());return all;}
    public static void main(String[] args)throws Exception {
        CoreTests.test("multipacks validate without adding inventory",()->{var l=line();CoreTests.equal(l.cans(),48L);var doc=new Purchases.Document("purchase-doc001","purchase","Supplier","INV1",null,now,10001,909,"","",null,Ledger.list(l));CoreTests.equal(doc.date(),null);CoreTests.equal(Ledger.totals(Ledger.opening(now)).stock(),20L);});
        CoreTests.test("partial receipt cost rounds cumulatively and fully",()->{var l=line();long a=Purchases.allocatedCost(l,0,17),b=Purchases.allocatedCost(l,17,31);CoreTests.equal(a+b,l.cost());CoreTests.reject(()->Purchases.allocatedCost(l,47,2));});
        CoreTests.test("invalid purchase totals quantities and GST rejected",()->{CoreTests.reject(()->new Purchases.Line("bad-line-00001","Monster",2,0,100,0,true));CoreTests.reject(()->new Purchases.Line("bad-line-00002","Monster",1,24,100,101,true));CoreTests.reject(()->new Purchases.Document("bad-doc-000001","purchase","Supplier","",now,now,100,0,"","",null,Ledger.list(line())));});
        CoreTests.test("expense has no stock lines",()->{var d=new Purchases.Document("expense-doc-001","expense","Transport","",now,now,500,0,"Travel","",null,Ledger.list());CoreTests.equal(d.lines().size(),0);CoreTests.reject(()->new Purchases.Document("expense-doc-002","expense","Travel","",now,now,10001,909,"Travel","",null,Ledger.list(line())));});
        CoreTests.test("invoice fingerprint normalizes supplier and reference",()->{var a=new Purchases.Document("invoice-first01","expense","SHOP"," X1 ",null,now,100,0,"","",null,Ledger.list());var b=new Purchases.Document("invoice-next001","expense"," shop ","x1",null,now,100,0,"","",null,Ledger.list());CoreTests.equal(a.invoiceKey(),b.invoiceKey());});
        CoreTests.test("receipt hashes retain original bytes and reject tampering",()->{byte[] jpg={(byte)255,(byte)216,(byte)255,0,1};var r=Purchases.receipt(jpg);CoreTests.equal(r.mime(),"image/jpeg");jpg[4]=9;CoreTests.equal(r.content()[4],(byte)1);CoreTests.reject(()->new Purchases.Receipt(r.hash(),r.mime(),jpg));CoreTests.reject(()->Purchases.receipt(new byte[]{1,2,3}));});
        CoreTests.test("version-2 full backup keeps purchase and original receipt",()->{var r=Purchases.receipt("%PDF-1.4\noriginal receipt".getBytes(java.nio.charset.StandardCharsets.UTF_8));var doc=new Purchases.Document("backup-doc-0001","purchase","Shop","INV2",null,now,10001,909,"","",r.hash(),Ledger.list(line()));var data=new Backup.Data(Ledger.opening(now),new Ledger.Prices(350,600),bundle(doc,r));var roundtrip=Backup.decode(Backup.encode(data));CoreTests.equal(Json.write(roundtrip.business()),Json.write(data.business()));CoreTests.equal(roundtrip.events().get(1).timestamp(),null);});
        CoreTests.test("backup rejects missing receipt and duplicate invoice",()->{var r=Purchases.receipt("%PDF-original".getBytes());var doc=new Purchases.Document("missing-doc001","purchase","Shop","INV3",now,now,10001,909,"","",r.hash(),Ledger.list(line()));CoreTests.reject(()->BusinessBackup.validate(bundle(doc,null),Ledger.opening(now)));var all=bundle(doc,r);all.put("documents",Ledger.list(Purchases.documentMap(doc),Purchases.documentMap(doc)));CoreTests.reject(()->BusinessBackup.validate(all,Ledger.opening(now)));});
        CoreTests.test("v1 backups remain readable without deleting new domain",()->{var old=Backup.decode(Backup.encode(new Backup.Data(Ledger.opening(now),new Ledger.Prices(350,600))));CoreTests.equal(old.business(),null);});
        CoreTests.test("undo/re-receive never allocates an extra rounding cent",()->{var l=line();long first=Purchases.remainingCost(l,0,0,17),last=Purchases.remainingCost(l,17,first,31);long replacement=Purchases.remainingCost(l,31,last,17);CoreTests.equal(last+replacement,l.cost());var tiny=new Purchases.Line("tiny-cost-line1","Monster",1,10000,1,0,true);CoreTests.equal(Purchases.remainingCost(tiny,1,1,9999),0L);});
        if(CoreTests.failed>0)throw new AssertionError("Purchase tests failed");System.out.println("PURCHASE CHECKS PASSED");
    }
}
